#!/usr/bin/env python3
from pathlib import Path
import subprocess, sys, re

FILES = {
    "seed_memory_garden_v90.py": "\nimport json\nimport re\nfrom datetime import datetime\nfrom pathlib import Path\n\nSTATE_FILE = Path(\"seed_memory_garden_v90_state.json\")\nMEMORIES_FILE = Path(\"seed_memory_garden_v90_memories.jsonl\")\nARCHIVE_FILE = Path(\"seed_memory_garden_v90_archive.jsonl\")\nSETTINGS_FILE = Path(\"seed_memory_garden_v90_settings.json\")\n\nDEFAULTS = {\n    \"version\": \"v90.0.0\",\n    \"auto_archive_startup_notes\": True,\n    \"auto_archive_low_value_notes\": True,\n    \"min_importance_candidate\": 75,\n    \"min_importance_auto_promote\": 92,\n    \"max_candidate_cards\": 25,\n    \"memory_context_limit\": 12,\n    \"note_source_file\": \"seed_organism_notes_v89.jsonl\",\n    \"no_raw_media_rule\": True\n}\n\nLOW_VALUE_PATTERNS = [\n    \"organism mode started\",\n    \"seed organism mode started\",\n    \"stores notes only\",\n    \"terminal window\",\n    \"command prompt\",\n    \"active window\",\n    \"safari webpage\",\n    \"firefox window\",\n    \"browser is showing\",\n    \"person of interest\",\n    \"episode\",\n    \"watching show\",\n    \"webpage with a login prompt\"\n]\n\nHIGH_VALUE_HINTS = [\n    \"decided\", \"wants\", \"prefers\", \"important\", \"todo\", \"next\", \"bug\", \"fixed\",\n    \"permission\", \"working\", \"green\", \"failed\", \"project\", \"seed\", \"memory\",\n    \"mac body\", \"organism\", \"wake\", \"avatar\", \"vision\", \"hearing\"\n]\n\ndef now():\n    return datetime.now().isoformat(timespec=\"seconds\")\n\ndef load_settings():\n    if SETTINGS_FILE.exists():\n        try:\n            d = DEFAULTS.copy()\n            d.update(json.loads(SETTINGS_FILE.read_text(errors=\"ignore\")))\n            d[\"version\"] = \"v90.0.0\"\n            return d\n        except Exception:\n            pass\n    SETTINGS_FILE.write_text(json.dumps(DEFAULTS, indent=4, ensure_ascii=False))\n    return DEFAULTS.copy()\n\ndef write_jsonl(path, row):\n    row.setdefault(\"created_at\", now())\n    row.setdefault(\"version\", \"v90.0.0\")\n    with path.open(\"a\") as f:\n        f.write(json.dumps(row, ensure_ascii=False) + \"\\n\")\n\ndef read_jsonl(path, limit=5000):\n    if not Path(path).exists():\n        return []\n    rows = []\n    for line in Path(path).read_text(errors=\"ignore\").splitlines()[-limit:]:\n        try:\n            rows.append(json.loads(line))\n        except Exception:\n            pass\n    return rows\n\ndef norm(text):\n    text = re.sub(r\"[^a-z0-9\u00e7\u011f\u0131\u00f6\u015f\u00fc\\s]\", \" \", str(text or \"\").lower())\n    return \" \".join(text.split())\n\ndef note_id(note):\n    return str(note.get(\"id\") or note.get(\"created_at\") or \"\")\n\ndef is_low_value(note):\n    summary = norm(note.get(\"summary\", \"\"))\n    source = note.get(\"source\", \"\")\n    if source == \"organism\" and \"organism mode started\" in summary:\n        return True\n    return any(p in summary for p in LOW_VALUE_PATTERNS)\n\ndef has_high_value_hint(note):\n    s = norm(note.get(\"summary\", \"\"))\n    tags = \" \".join([norm(t) for t in note.get(\"tags\", [])])\n    return any(h in s or h in tags for h in HIGH_VALUE_HINTS)\n\ndef memory_type_for(note):\n    s = norm(note.get(\"summary\", \"\"))\n    tags = \" \".join([norm(t) for t in note.get(\"tags\", [])])\n    if \"prefers\" in s or \"wants\" in s or \"likes\" in s:\n        return \"preference\"\n    if \"bug\" in s or \"failed\" in s or \"fixed\" in s or \"permission\" in s:\n        return \"technical_state\"\n    if \"green\" in s or \"working\" in s or \"ready true\" in s:\n        return \"milestone\"\n    if \"todo\" in s or \"next\" in s:\n        return \"open_loop\"\n    if \"seed\" in s or \"organism\" in s or \"mac body\" in s or \"wake\" in s:\n        return \"project_context\"\n    if \"vision\" in tags or \"hearing\" in tags:\n        return \"observation\"\n    return \"general\"\n\ndef reviewed_ids():\n    ids = set()\n    for row in read_jsonl(MEMORIES_FILE):\n        ids.add(str(row.get(\"source_note_id\", \"\")))\n    for row in read_jsonl(ARCHIVE_FILE):\n        ids.add(str(row.get(\"source_note_id\", \"\")))\n    return ids\n\ndef load_notes():\n    settings = load_settings()\n    return read_jsonl(settings.get(\"note_source_file\", \"seed_organism_notes_v89.jsonl\"))\n\ndef classify_note(note):\n    settings = load_settings()\n    importance = int(note.get(\"importance\", 0) or 0)\n    low = is_low_value(note)\n    high_hint = has_high_value_hint(note)\n    source = note.get(\"source\", \"unknown\")\n    summary = str(note.get(\"summary\", \"\")).strip()\n\n    if not summary:\n        return {\"action\": \"archive\", \"reason\": \"empty_summary\", \"score\": 0}\n\n    if low:\n        return {\"action\": \"archive\", \"reason\": \"low_value_or_startup_note\", \"score\": min(importance, 35)}\n\n    score = importance\n    if high_hint:\n        score += 12\n    if source in {\"hearing\", \"vision\"}:\n        score += 2\n    score = min(score, 100)\n\n    if score >= int(settings.get(\"min_importance_auto_promote\", 92)):\n        return {\"action\": \"promote\", \"reason\": \"high_importance\", \"score\": score}\n\n    if score >= int(settings.get(\"min_importance_candidate\", 75)):\n        return {\"action\": \"candidate\", \"reason\": \"review_candidate\", \"score\": score}\n\n    return {\"action\": \"ignore\", \"reason\": \"not_important_enough\", \"score\": score}\n\ndef note_to_memory(note, decision=None):\n    decision = decision or classify_note(note)\n    return {\n        \"memory_id\": \"mem_\" + note_id(note).replace(\"note_\", \"\"),\n        \"source_note_id\": note_id(note),\n        \"memory_type\": memory_type_for(note),\n        \"summary\": str(note.get(\"summary\", \"\")).strip(),\n        \"importance\": int(note.get(\"importance\", 0) or 0),\n        \"score\": decision.get(\"score\"),\n        \"tags\": note.get(\"tags\", []),\n        \"metadata\": note.get(\"metadata\", {}),\n        \"created_from_note_at\": note.get(\"created_at\"),\n        \"raw_audio_saved\": False,\n        \"raw_screenshot_saved\": False,\n        \"raw_transcript_saved\": False,\n        \"note_only_mode\": True\n    }\n\ndef digest_notes(apply=False):\n    ids = reviewed_ids()\n    notes = load_notes()\n    cards = []\n    promoted = 0\n    archived = 0\n\n    for note in notes:\n        nid = note_id(note)\n        if not nid or nid in ids:\n            continue\n        decision = classify_note(note)\n        card = {\"note_id\": nid, \"decision\": decision, \"source\": note.get(\"source\"), \"summary\": note.get(\"summary\"), \"importance\": note.get(\"importance\"), \"tags\": note.get(\"tags\", [])}\n        cards.append(card)\n\n        if apply and decision[\"action\"] == \"promote\":\n            write_jsonl(MEMORIES_FILE, note_to_memory(note, decision))\n            promoted += 1\n        elif apply and decision[\"action\"] in {\"archive\", \"ignore\"}:\n            write_jsonl(ARCHIVE_FILE, {\"source_note_id\": nid, \"reason\": decision[\"reason\"], \"summary\": note.get(\"summary\"), \"decision\": decision})\n            archived += 1\n\n    state = {\"created_at\": now(), \"version\": \"v90.0.0\", \"ok\": True, \"apply\": apply, \"promoted\": promoted, \"archived\": archived, \"cards\": cards[:int(load_settings().get(\"max_candidate_cards\", 25))], \"unreviewed_count\": len(cards)}\n    STATE_FILE.write_text(json.dumps(state, indent=4, ensure_ascii=False))\n    return state\n\ndef promote_note(note_id_value):\n    notes = load_notes()\n    target = None\n    for note in notes:\n        if note_id(note) == str(note_id_value):\n            target = note\n            break\n    if not target:\n        return {\"ok\": False, \"error\": \"note not found\", \"note_id\": note_id_value}\n    mem = note_to_memory(target, {\"score\": 100, \"reason\": \"manual_promote\"})\n    write_jsonl(MEMORIES_FILE, mem)\n    return {\"ok\": True, \"promoted\": mem}\n\ndef promote_latest_candidate():\n    state = digest_notes(apply=False)\n    for card in state[\"cards\"]:\n        if card[\"decision\"][\"action\"] in {\"candidate\", \"promote\"}:\n            return promote_note(card[\"note_id\"])\n    return {\"ok\": False, \"error\": \"no candidate found\"}\n\ndef archive_note(note_id_value, reason=\"manual_archive\"):\n    write_jsonl(ARCHIVE_FILE, {\"source_note_id\": str(note_id_value), \"reason\": reason})\n    return {\"ok\": True, \"archived\": str(note_id_value), \"reason\": reason}\n\ndef memories(limit=20):\n    return read_jsonl(MEMORIES_FILE, limit)\n\ndef garden_context(limit=None):\n    limit = int(limit or load_settings().get(\"memory_context_limit\", 12))\n    rows = memories(limit)\n    if not rows:\n        return \"Seed Memory Garden: no promoted memories yet.\"\n    lines = [\"Seed Memory Garden promoted memories:\"]\n    for r in rows[-limit:]:\n        lines.append(f\"- [{r.get('memory_type')}] {r.get('summary')}\")\n    return \"\\n\".join(lines)\n\ndef daily_summary():\n    mems = memories(50)\n    notes = load_notes()[-50:]\n    recent = mems[-12:] if mems else notes[-12:]\n    if not recent:\n        return {\"ok\": True, \"summary\": \"No meaningful notes yet.\"}\n    bullets = []\n    for r in recent:\n        s = str(r.get(\"summary\", \"\")).strip()\n        if s:\n            bullets.append(\"- \" + s)\n    return {\"ok\": True, \"summary\": \"Seed day summary:\\n\" + \"\\n\".join(bullets[-12:])}\n\ndef status():\n    notes = load_notes()\n    mems = memories(5000)\n    archived = read_jsonl(ARCHIVE_FILE, 5000)\n    unreviewed = [n for n in notes if note_id(n) not in reviewed_ids()]\n    data = {\n        \"created_at\": now(),\n        \"version\": \"v90.0.0\",\n        \"ok\": True,\n        \"notes_total\": len(notes),\n        \"memories_total\": len(mems),\n        \"archived_total\": len(archived),\n        \"unreviewed_total\": len(unreviewed),\n        \"settings\": load_settings(),\n        \"latest_memories\": mems[-5:]\n    }\n    STATE_FILE.write_text(json.dumps(data, indent=4, ensure_ascii=False))\n    return data\n\ndef show_status():\n    print(\"\\n=== SEED v90 MEMORY GARDEN STATUS ===\")\n    print(json.dumps(status(), indent=4, ensure_ascii=False))\n\ndef show_review(apply=False):\n    print(\"\\n=== SEED v90 MEMORY GARDEN REVIEW ===\")\n    print(json.dumps(digest_notes(apply=apply), indent=4, ensure_ascii=False))\n\ndef show_memories(limit=20):\n    print(\"\\n=== SEED v90 PROMOTED MEMORIES ===\")\n    print(json.dumps(memories(limit), indent=4, ensure_ascii=False))\n\nif __name__ == \"__main__\":\n    import sys\n    arg = sys.argv[1] if len(sys.argv) > 1 else \"status\"\n    if arg == \"status\":\n        show_status()\n    elif arg == \"review\":\n        show_review(apply=False)\n    elif arg == \"digest\":\n        show_review(apply=True)\n    elif arg == \"memories\":\n        show_memories(int(sys.argv[2]) if len(sys.argv) > 2 else 20)\n    elif arg == \"promote\":\n        print(promote_note(sys.argv[2]))\n    elif arg == \"promote-latest\":\n        print(promote_latest_candidate())\n    elif arg == \"archive\":\n        print(archive_note(sys.argv[2], \"manual_archive\"))\n    elif arg == \"summary\":\n        print(daily_summary()[\"summary\"])\n    elif arg == \"context\":\n        print(garden_context())\n    else:\n        print(\"Commands: status | review | digest | memories [n] | promote <note_id> | promote-latest | archive <note_id> | summary | context\")\n",
    "seed_natural_intent_router_v90.py": "\nimport re\n\ndef norm(text):\n    return \" \".join(str(text or \"\").strip().lower().split())\n\ndef handle_natural_intent_v90(user_message):\n    raw = str(user_message or \"\").strip()\n    text = norm(raw)\n    if not text or raw.startswith(\"/\"):\n        return None\n\n    if text in {\"v90 status\", \"garden status\", \"memory garden status\"}:\n        from seed_memory_garden_v90 import show_status\n        show_status()\n        return \"handled\"\n\n    if text in {\"review notes\", \"review organism notes\", \"memory garden review\", \"garden review\"}:\n        from seed_memory_garden_v90 import show_review\n        show_review(False)\n        return \"handled\"\n\n    if text in {\"digest notes\", \"digest organism notes\", \"garden digest\", \"clean notes\"}:\n        from seed_memory_garden_v90 import show_review\n        show_review(True)\n        return \"handled\"\n\n    if text in {\"show memories\", \"garden memories\", \"promoted memories\"}:\n        from seed_memory_garden_v90 import show_memories\n        show_memories(20)\n        return \"handled\"\n\n    if text in {\"promote latest\", \"promote latest note\", \"promote latest candidate\"}:\n        from seed_memory_garden_v90 import promote_latest_candidate\n        print(promote_latest_candidate())\n        return \"handled\"\n\n    m = re.match(r\"promote note\\s+(.+)$\", raw, flags=re.I)\n    if m:\n        from seed_memory_garden_v90 import promote_note\n        print(promote_note(m.group(1).strip()))\n        return \"handled\"\n\n    m = re.match(r\"archive note\\s+(.+)$\", raw, flags=re.I)\n    if m:\n        from seed_memory_garden_v90 import archive_note\n        print(archive_note(m.group(1).strip()))\n        return \"handled\"\n\n    if text in {\"day summary\", \"garden summary\", \"memory summary\"}:\n        from seed_memory_garden_v90 import daily_summary\n        print(daily_summary()[\"summary\"])\n        return \"handled\"\n\n    return None\n",
    "seed_v90_systems.py": "\nimport json\nfrom datetime import datetime\nfrom pathlib import Path\n\nSTATE_FILE = Path(\"seed_v90_systems_state.json\")\n\ndef now():\n    return datetime.now().isoformat(timespec=\"seconds\")\n\ndef safe(title, summary, fn):\n    try:\n        data = fn()\n        return {\"title\": title, \"summary\": summary, \"status\": \"ok\" if data.get(\"ok\", True) else \"warning\", \"data\": data}\n    except Exception as e:\n        return {\"title\": title, \"summary\": summary, \"status\": \"error\", \"error\": str(e)}\n\ndef build_v90_state():\n    cards = [\n        safe(\"Memory Garden\", \"Reviews organism notes and promotes only meaningful memories.\", lambda: __import__(\"seed_memory_garden_v90\", fromlist=[\"status\"]).status()),\n        safe(\"Garden Context\", \"Creates compact memory context for future Seed chat.\", lambda: {\"ok\": True, \"context\": __import__(\"seed_memory_garden_v90\", fromlist=[\"garden_context\"]).garden_context()}),\n    ]\n    data = {\"created_at\": now(), \"version\": \"v90.0.0\", \"ok\": all(c[\"status\"] != \"error\" for c in cards), \"cards\": cards}\n    STATE_FILE.write_text(json.dumps(data, indent=4, ensure_ascii=False))\n    return data\n\ndef show_v90_status():\n    data = build_v90_state()\n    print(\"\\n=== SEED v90 MEMORY GARDEN STATUS ===\")\n    print(f\"OK: {data['ok']}\")\n    for c in data[\"cards\"]:\n        print(f\"- {c['title']}: {c['status']} \u2014 {c['summary']}\")\n\nif __name__ == \"__main__\":\n    show_v90_status()\n",
    "seed_v90_gate.py": "\nimport json, subprocess, sys\nfrom datetime import datetime\nfrom pathlib import Path\n\nMODULES = [\"seed_memory_garden_v90.py\", \"seed_natural_intent_router_v90.py\", \"seed_v90_systems.py\", \"seed_v90_gate.py\"]\n\ndef now():\n    return datetime.now().isoformat(timespec=\"seconds\")\n\ndef comp(m):\n    p = subprocess.run([sys.executable, \"-m\", \"py_compile\", m], capture_output=True, text=True, timeout=30)\n    return {\"module\": m, \"ok\": p.returncode == 0, \"stderr\": p.stderr[-1000:]}\n\ndef run_v90_gate():\n    checks = [comp(m) for m in MODULES]\n    modules_ok = all(c[\"ok\"] for c in checks)\n    details = {}\n    try:\n        garden = __import__(\"seed_memory_garden_v90\", fromlist=[\"classify_note\", \"garden_context\", \"status\"])\n        low_note = {\"id\":\"note_test_low\", \"source\":\"vision\", \"summary\":\"A Firefox window is open displaying Person of Interest episode.\", \"importance\":68, \"tags\":[\"firefox\"]}\n        high_note = {\"id\":\"note_test_high\", \"source\":\"vision\", \"summary\":\"Seed Mac body keyboard permissions are now working after Accessibility permission fix.\", \"importance\":86, \"tags\":[\"seed\",\"mac body\",\"permission\"]}\n        low_ok = garden.classify_note(low_note)[\"action\"] == \"archive\"\n        high_ok = garden.classify_note(high_note)[\"action\"] in {\"candidate\", \"promote\"}\n        status = garden.status()\n        garden_ok = status.get(\"ok\") is True\n        details = {\"low_note_test\": garden.classify_note(low_note), \"high_note_test\": garden.classify_note(high_note), \"status\": status}\n    except Exception as e:\n        low_ok = False\n        high_ok = False\n        garden_ok = False\n        details = {\"error\": str(e)}\n    r = {\"created_at\": now(), \"version\": \"v90.0.0\", \"ready\": modules_ok and low_ok and high_ok and garden_ok, \"modules_ok\": modules_ok, \"low_note_filter_ok\": low_ok, \"high_note_candidate_ok\": high_ok, \"garden_ok\": garden_ok, \"module_checks\": checks, \"details\": details}\n    Path(\"seed_v90_gate_report.json\").write_text(json.dumps(r, indent=4, ensure_ascii=False))\n    return r\n\ndef show_v90_gate():\n    r = run_v90_gate()\n    print(\"\\n=== SEED v90 MEMORY GARDEN GATE ===\")\n    print(f\"Ready: {r['ready']}\")\n    print(f\"Modules OK: {r['modules_ok']}\")\n    print(f\"Low Note Filter OK: {r['low_note_filter_ok']}\")\n    print(f\"High Note Candidate OK: {r['high_note_candidate_ok']}\")\n    print(f\"Garden OK: {r['garden_ok']}\")\n    print(f\"Details: {r['details']}\")\n\nif __name__ == \"__main__\":\n    show_v90_gate()\n"
}

for path, text in FILES.items():
    Path(path).write_text(text.strip() + "\n")
    print("Wrote", path)

p = Path("seed_commands.py")
text = p.read_text(errors="ignore") if p.exists() else "def handle_chat_command(user_message,*args,**kwargs): return None\n"
if "_seed_v90_previous_handle_chat_command" not in text:
    text += """
# v90 memory garden router.
try:
    _seed_v90_previous_handle_chat_command = handle_chat_command

    def handle_chat_command(user_message, *args, **kwargs):
        try:
            from seed_natural_intent_router_v90 import handle_natural_intent_v90
            handled = handle_natural_intent_v90(user_message)
            if handled == "handled":
                return "handled"
        except Exception as error:
            print(f"v90 natural router error: {error}")
            return "handled"
        return _seed_v90_previous_handle_chat_command(user_message, *args, **kwargs)
except Exception:
    pass
"""
    p.write_text(text)
    print("Patched seed_commands.py")

p = Path("seed_config.py")
text = p.read_text(errors="ignore") if p.exists() else 'SEED_VERSION = "v90.0.0"\n'
text = re.sub(r'^SEED_VERSION\s*=\s*".*?"', 'SEED_VERSION = "v90.0.0"', text, flags=re.M)
if "SEED_V90_MEMORY_GARDEN" not in text:
    text += "\nSEED_V90_MEMORY_GARDEN = True\nSEED_V90_NOTE_TO_MEMORY = True\n"
p.write_text(text)
print("Updated seed_config.py")

p = Path("Seed_Core.md")
text = p.read_text(errors="ignore") if p.exists() else ""
if "Seed v90.0.0 — Memory Garden" not in text:
    text += """
## Seed v90.0.0 — Memory Garden

Turns organism notes into reviewed memories:
- Reviews note-only organism observations.
- Archives low-value notes.
- Promotes only meaningful memories.
- Keeps a compact memory context for future Seed chat.
- Supports manual promote/archive and daily summary.

Commands:
- python seed_memory_garden_v90.py status
- python seed_memory_garden_v90.py review
- python seed_memory_garden_v90.py digest
- python seed_memory_garden_v90.py memories
- python seed_memory_garden_v90.py promote <note_id>
- python seed_memory_garden_v90.py promote-latest
- python seed_memory_garden_v90.py summary
"""
p.write_text(text)
print("Updated Seed_Core.md")

p = Path(".gitignore")
text = p.read_text(errors="ignore") if p.exists() else ""
block = """
# Seed v90 memory garden runtime
seed_memory_garden_v90_state.json
seed_memory_garden_v90_memories.jsonl
seed_memory_garden_v90_archive.jsonl
seed_memory_garden_v90_settings.json
seed_v90_systems_state.json
seed_v90_gate_report.json
"""
if "Seed v90 memory garden runtime" not in text:
    text += "\n" + block
p.write_text(text)
print("Updated .gitignore")

for m in list(FILES.keys()) + ["seed_commands.py"]:
    proc = subprocess.run([sys.executable, "-m", "py_compile", m], capture_output=True, text=True, timeout=30)
    print("$ python -m py_compile", m)
    if proc.returncode == 0:
        print("OK")
    else:
        print(proc.stderr)
        sys.exit(proc.returncode)

print("\nSeed v90 Memory Garden installer complete.")
